import{Ct as e,at as t,it as n,ot as r,st as i,tt as a,yt as o}from"./chunks/framework.B-d2E8F-.js";import{t as s}from"./chunks/DoctorSliceHero.YUMJV86N.js";var c=JSON.parse(`{"title":"LaTeX compilation environment","description":"","frontmatter":{},"headers":[],"relativePath":"guide/latex-compilation.md","filePath":"guide/latex-compilation.md"}`),l=Object.assign({name:`guide/latex-compilation.md`},{setup(c){return(c,l)=>{let u=e(`wa-icon`);return o(),n(`div`,null,[l[6]||=t(`<h1 id="latex-compilation-environment" tabindex="-1">LaTeX compilation environment <a class="header-anchor" href="#latex-compilation-environment" aria-label="Permalink to “LaTeX compilation environment”">​</a></h1><p>TeXRA&#39;s agents work on derivations, proofs, and the papers that record them. Most of that work happens in LaTeX source, so several features rely on a working LaTeX distribution on your system, such as compiling previews or processing generated <code>latexdiff</code> files.</p><h2 id="required-latex-distribution" tabindex="-1">Required LaTeX distribution <a class="header-anchor" href="#required-latex-distribution" aria-label="Permalink to “Required LaTeX distribution”">​</a></h2><p>You need a working LaTeX distribution installed, such as:</p><ul><li><strong>Windows</strong>: MiKTeX or TeX Live</li><li><strong>macOS</strong>: MacTeX (includes TeX Live)</li><li><strong>Linux</strong>: TeX Live (often available through the package manager)</li></ul><p>A working LaTeX installation is required for features like compiling diffs and TikZ previews.</p><p>Make sure the <code>latexmk</code> command is available (preferred by TeXRA) or at least <code>pdflatex</code>. Both must be reachable from your system&#39;s command line. <code>texra doctor</code> verifies the whole toolchain in one pass, on any platform:</p>`,7),i(s,{rows:[{state:`pass`,name:`LaTeX latexmk`,message:`LaTeX build orchestration`},{state:`pass`,name:`LaTeX pdflatex`,message:`PDFLaTeX compiler`},{state:`pass`,name:`LaTeX bibtex`,message:`BibTeX bibliography processing`},{state:`pass`,name:`LaTeX latexdiff`,message:`LaTeX diff generation`}]}),l[7]||=t(`<p class="hero-caption">The doctor&#39;s LaTeX rows confirm each binary is on PATH. The same check works for extension and CLI users alike.</p><p>Read the <a href="./installation.html">installation guide</a> for details on installing LaTeX and other dependencies such as Perl (required for <code>latexdiff</code>).</p><h2 id="integration-with-latex-workshop" tabindex="-1">Integration with LaTeX Workshop <a class="header-anchor" href="#integration-with-latex-workshop" aria-label="Permalink to “Integration with LaTeX Workshop”">​</a></h2><p>TeXRA works alongside the <a href="https://marketplace.visualstudio.com/items?itemName=James-Yu.latex-workshop" target="_blank" rel="noreferrer">LaTeX Workshop</a> extension, which provides compilation, previewing, and IntelliSense. If the extension isn&#39;t detected and your workspace contains LaTeX files, TeXRA prompts you to install it. On a workspace without LaTeX files there is no prompt; you can still install it from the Dashboard&#39;s LaTeX tab.</p><p><strong>Workflow interaction:</strong></p><p>TeXRA uses LaTeX Workshop when available. For example, after generating a comparison file with its <code>latexdiff</code> features (read the <a href="./latex-diff.html">LaTeX diff guide</a>), TeXRA attempts to trigger LaTeX Workshop&#39;s build and view commands automatically, so you can compile and see the visualized changes in the resulting PDF.</p><p><strong>Recommended setting:</strong></p><p>To keep your project directory clean, configure LaTeX Workshop to place its build output files (such as <code>.aux</code>, <code>.log</code>, <code>.pdf</code>) in a separate subdirectory. TeXRA is aware of this common practice.</p><p>The Dashboard&#39;s LaTeX tab applies this for you. Its recommended settings list includes <strong>LaTeX Output Directory</strong> (<code>latex-workshop.latex.outDir</code>, set to <code>%DIR%/build/</code>) and <strong>Explorer Auto-Reveal Exclude</strong> (so the <code>build/</code> folder stays out of the Explorer), each with an <strong>Apply</strong> button, plus <strong>Apply All</strong> to set both at once.</p><p>If you prefer to set it by hand, LaTeX Workshop is a separate VS Code extension, so the setting lives in VS Code&#39;s own settings:</p>`,10),a(`ol`,null,[a(`li`,null,[l[0]||=r(`Open VS Code Settings (`,-1),i(u,{library:`texra`,name:`gear`}),l[1]||=r(` icon or `,-1),l[2]||=a(`code`,null,`Ctrl+,`,-1),l[3]||=r(`).`,-1)]),l[4]||=a(`li`,null,[r(`Search for `),a(`code`,null,`Latex-workshop: Latex: Out Dir`),r(`.`)],-1),l[5]||=a(`li`,null,[r(`Set the value to `),a(`code`,null,`%DIR%/build/`),r(`.`)],-1)]),l[8]||=t(`<p>This directs build files to a <code>build/</code> subdirectory in your project, keeping your main source directory uncluttered. TeXRA primarily works with the source <code>.tex</code> files, but a clean setup helps the overall workflow, especially when using LaTeX Workshop for compilation and previewing.</p><h2 id="alternative-online-compilers-e-g-overleaf" tabindex="-1">Alternative: online compilers (e.g., Overleaf) <a class="header-anchor" href="#alternative-online-compilers-e-g-overleaf" aria-label="Permalink to “Alternative: online compilers (e.g., Overleaf)”">​</a></h2><p>Setting up and maintaining a local LaTeX distribution can be difficult because of complex dependencies or system configurations. If local compilation keeps failing when you preview <code>latexdiff</code> outputs or TikZ figures, an online LaTeX editor and compiler such as <a href="https://www.overleaf.com" target="_blank" rel="noreferrer">Overleaf</a> is an alternative. Upload the <code>.tex</code> files generated by TeXRA (such as diff files or standalone TikZ files) to Overleaf to compile and view them there.</p>`,3)])}}});export{c as __pageData,l as default};